import{_ as c,l,o as a,c as n,v as r,p as d,x as o,d as s,i,S as p}from"./chunks/framework.InCnrqk-.js";const R=JSON.parse('{"title":"RCU 读者","description":"","frontmatter":{"title":"RCU 读者","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/rcu-read.md","filePath":"cs/rcu-read.md","lastUpdated":1789023840000}'),_={name:"cs/rcu-read.md"};function u(h,e,m,E,f,C){const t=l("Mermaid");return a(),n("div",null,[e[1]||(e[1]=r('<h1 id="rcu-读者" tabindex="-1">RCU 读者 <a class="header-anchor" href="#rcu-读者" aria-label="Permalink to &quot;RCU 读者&quot;">​</a></h1><div class="epigraph"><p>读—拷贝—更新让读者在没有任何锁的路径上遍历结构；写者改的是新副本，旧副本要等所有读者离开后再释放。</p><footer>—— 据 McKenney and Slingwine, Read-Copy Update, 1998 起；McKenney, What Is RCU, Fundamentally? 整理</footer></div><p><a href="/cs/completion">上一课</a>会合一次性事件，读者仍可能持锁或重试。<a href="/cs/rwlock">rwlock</a> 读侧写计数；<a href="/cs/seqlock">seqlock</a> 要求数据小可重试。缺口是内核链表、路由一类：<strong>读者极多、不能失败、不能睡在读侧</strong>，写者可另做副本。本课只钉读者规则：<code>rcu_read_lock</code> 区间内指针仍有效。宽限期下一课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>读者若拿 rwlock，缓存行与延迟都回去了。RCU 读者：关抢占（或等价地声明读侧临界区），用 <code>rcu_dereference</code> 加载指针，遍历。写者：拷贝结点、填新数据、<code>rcu_assign_pointer</code> 把链表指针改到新结点，旧结点先不释放。缺口不是 completion 的粘性位，而是<strong>读侧零原子、零失败</strong>，正确性靠「没有读者还拿着旧指针」这一事后条件。</p><p><span class="marginnote">读侧临界区不能睡眠（普通 RCU）。否则宽限期无法结束。SRCU 允许睡，代价另一套，主干先记不可睡。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>读者：<code>rcu_read_lock(); p = rcu_dereference(gp); ...; rcu_read_unlock();</code>。在这之间，写者保证不释放读者可能拿到的对象。加载必须带依赖或 acquire，防止编译器把解引用提前——对接屏障课。写者互斥仍用 mutex/自旋保护「谁在改这棵结构」。</p>',8)),(a(),d(p,null,{default:o(()=>[i(t,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20R%5B%22rcu_read_lock%20%E9%81%8D%E5%8E%86%22%5D%20--%3E%20P%5B%22%E7%9C%8B%E8%A7%81%E6%97%A7%E6%88%96%E6%96%B0%E6%95%B4%E7%89%88%22%5D%0A%20%20W%5B%22%E5%86%99%E8%80%85%E6%8D%A2%E6%8C%87%E9%92%88%22%5D%20--%3E%20OLD%5B%22%E6%97%A7%E7%BB%93%E7%82%B9%E5%BB%B6%E5%90%8E%E9%87%8A%E6%94%BE%22%5D%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[s(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=r('<p>与<a href="/cs/kernel-preempt">内核抢占</a>：读侧关抢占是常见实现，使「当前 CPU 过了静止点」可检测。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>读者永远看见一致的旧版或新版，不像 seqlock 那样中间态重试。写延迟转到「何时能 free」。多读者并行、不写共享锁字，这是 RCU 存在的理由。误用：在读侧外拿着指针去睡，再解引用——对象可能已释放。本课把这条当纪律，回收时机下一课。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 <code>call_rcu</code> 的回调队列写完，不比较所有 RCU 变体。用户态 RCU 存在，主干以内核为准。无锁链表的 ABA 还没出场。</p><p>后课默认：读者在 RCU 临界区内指针有效。写者何时能释放旧对象，下一课宽限期。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>RCU 读者无锁、不失败、不可睡（普通 RCU）。</li><li>写者换指针，旧对象先留着。</li><li>何时能 free 是宽限期课。</li><li>出处：McKenney and Slingwine；McKenney, <em>What Is RCU, Fundamentally?</em>。</li></ul>',8))])}const B=c(_,[["render",u]]);export{R as __pageData,B as default};
